pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    StaxLPStaking c;
    function setUp() public { c = new StaxLPStaking(address(this), address(this)); }
    function testRegression_property() public {
        address newDistributor = address(0x123);
        vm.prank(c.owner());
        c.setRewardDistributor(newDistributor);
        c.addReward(address(0x456));
        assertTrue(c.rewardDistributor() == address(0x123));
    }
}
